<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder\TrustedClientDynamicallyRegisteredAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientDynamicallyRegisteredAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientDynamicallyRegisteredAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that isDynamicallyRegistered returns null on a freshly created holder.
     */
    public function testDynamicallyRegisteredNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientDynamicallyRegisteredAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isDynamicallyRegisteredAssigned());
        $this->assertNull($holder->isDynamicallyRegistered());
    }
}
class ImplWithTrustedClientDynamicallyRegisteredAttributeHolderUnitTest
{
    use TrustedClientDynamicallyRegisteredAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedDynamicallyRegisteredRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultDynamicallyRegistered();
    }
}
